private fun symbol(name: String, viewport: Float, translateY: Float, autoMirror: Boolean, pathData: String): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = viewport, viewportHeight = viewport, autoMirror = autoMirror)
        .addGroup(translationY = translateY)
        .addPath(pathData = addPathNodes(pathData), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()
